from work import *
id='local040'
init(id,'联合树木记录，tree_id识别树木，ZIP对齐收入','trees data', '''# 独立题解
题目：“In the combined dataset that unifies the trees data with the income data by ZIP code, filling missing ZIP values where necessary, which three boroughs, restricted to records with median and mean income both greater than zero and a valid borough name, contain the highest number of trees, and what is the average mean income for each of these three boroughs?”
无业务文档。先树表与收入按ZIP完整外连接，合并ZIP=coalesce(t.zipcode,i.zipcode)；填补只来自另一表，不虚构地理推断。无树的收入行没有borough，最终有效borough筛选自然剔除。筛选median和mean均>0，borough非NULL非空，并验证数据库实际名字是否异常。
按borough统计树木数量，验证tree_id唯一和收入ZIP唯一决定是否count行等于树实体。最终平均收入是在符合条件联合记录上avg(Estimate_Mean_income)，即每棵树权重；不是每个ZIP等权，也不是按收入Estimate_Total家庭数权重。按树数降序取严格前三，并列用borough排序确定；不限制存活状态。
''')
query(id,'SELECT count(*) rows,count(distinct tree_id) tree_ids,sum(tree_id IS NULL) missing_id,sum(zipcode IS NULL) missing_zip,sum(boroname IS NULL OR trim(boroname)=\'\') missing_borough FROM trees','tree-keys.json')
query(id,'SELECT count(*) rows,count(distinct zipcode) zips,sum(zipcode IS NULL) missing_zip,sum(Estimate_Mean_income>0 AND Estimate_Median_income>0) positive FROM income_trees','income-keys.json')
query(id,'SELECT boroname,count(*) n FROM trees GROUP BY 1 ORDER BY 2 DESC','borough-values.json')
base='''WITH combined AS (SELECT t.tree_id,t.boroname,coalesce(t.zipcode,i.zipcode) zipcode,i.Estimate_Median_income median_income,i.Estimate_Mean_income mean_income,i.Estimate_Total households FROM trees t FULL OUTER JOIN income_trees i ON t.zipcode=i.zipcode), eligible AS (SELECT * FROM combined WHERE median_income>0 AND mean_income>0 AND boroname IS NOT NULL AND trim(boroname)<>''), boroughs AS (SELECT boroname,count(tree_id) tree_count,avg(mean_income) average_mean_income FROM eligible GROUP BY boroname) '''
query(id,base+'SELECT * FROM boroughs ORDER BY tree_count DESC','borough-results.json')
query(id,base+'SELECT boroname,count(*) zip_count,avg(mean_income) zip_equal_mean,sum(mean_income*households)*1.0/sum(households) household_weighted_mean FROM (SELECT DISTINCT boroname,zipcode,mean_income,households FROM eligible) GROUP BY boroname','income-weight-alternatives.json')
query(id,base+'SELECT count(*) combined_rows,sum(tree_id IS NULL) income_only,sum(mean_income IS NULL) missing_income,(SELECT count(*) FROM eligible) eligible_rows FROM combined','join-conservation.json')
fields={'population.eligibility':{'value':'median>0 and mean>0, non-null nonblank borough; all tree statuses allowed','basis':'request','quote':'restricted to records with median and mean income both greater than zero and a valid borough name'},'population.conditions':{'value':['ZIP full join, coalesce ZIP, positive median and mean, valid borough'],'basis':'request','quote':'unifies the trees data with the income data by ZIP code, filling missing ZIP values where necessary'},'population.time':'n/a','measure.formula':{'value':{'op':'custom','description':'Per borough count(tree_id) in eligible joined records and average mean income across tree records; rank by count, strict top3'},'basis':'assumed','rationale':'Average is at combined record grain, tree-row weighted rather than ZIP or household weighted'},'grouping':{'value':['boroname'],'basis':'request','quote':'three boroughs'},'selection':{'value':{'n':3,'orderBy':'tree_count DESC, boroname ASC'},'basis':'request','quote':'three boroughs'},'selection.ties':'strict','output':{'value':{'rowMode':'top_n','rowCount':3,'columns':['boroname','tree_count','average_mean_income']},'basis':'request','quote':'highest number of trees, and what is the average mean income'}}
finish(id,fields,base+'SELECT * FROM boroughs ORDER BY tree_count DESC,boroname LIMIT 3',{'algorithm':'Full ZIP join; positive both income, valid borough; count trees, tree-row weighted mean; strict top3','assumptions':['valid borough=nonempty observed borough name','tree record income average, not ZIP-equal']});progress(id,'frozen');reveal(id)
